def count_passing_ways(n: int, m: int) -> int:
    if n < 1 or m < 1:
        raise ValueError("n and m must be positive values")

    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        dp[i] = (dp[i - 1] * 2) % 1000000007
        for j in range(1, i + 1):
            if j != i:
                dp[i] = (dp[i] + dp[j]) % 1000000007

    return dp[n]

