def count_partitions(n: int, k: int, x: int) -> int:
    if n < 0 or k < 0 or x < 0:
        raise ValueError("n, k, and x must all be non-negative")
    if k == 0:
        return 1
    if n == 0:
        return 0
    if n - x < 0:
        return count_partitions(n, k - 1, x)
    return count_partitions(n - x, k, x) + count_partitions(n, k - 1, x)

def count_sequences(n, last, memo):
    if n > last // 2:
        return 0
    if n == last:
        return 1
    if n not in memo:
        memo[n] = count_sequences(n + 1, n, memo) + count_sequences(n + 1, last, memo)
    return memo[n]

