def vigenere_decrypt(key: str, ciphertext: str) -> str:
    # map each letter of the alphabet to its index in the alphabetical order
    alphabet_indexes = {c: i for i, c in enumerate(string.ascii_uppercase)}

    # iterate through the ciphertext and decrypt each letter based on the key
    plaintext = ""
    for i, cipherletter in enumerate(ciphertext):
